head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00005";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — registYn, param.method, exmptObjDisclsYn, messageStr

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00005.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        if ((String(((dma_pageContext.get("registYn") ?? "")) == null ? '' : ((dma_pageContext.get("registYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("registYn") ?? "")) == null ? '' : ((dma_pageContext.get("registYn") ?? "")))) === 'Y' && '' + dma_disclosureVo.get("applNo") + ''.length === 14) {
            if (('99840' === '' + dma_disclosureVo.get("formCd") + '') || ('70970' === '' + dma_disclosureVo.get("formCd") + '')) {
                parent.fn_registerProcess_exmpt('' + dma_disclosureVo.get("applNo") + '', '' + dma_disclosureVo.get("docNo") + '', '' + dma_disclosureVo.get("formCd") + '', '' + dma_disclosureVo.get("formVer") + '', '' + dma_disclosureVo.get("wrtrptMaindocTpCd") + '', (String(((dma_pageContext.get("method") ?? "")) == null ? '' : ((dma_pageContext.get("method") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("method") ?? "")) == null ? '' : ((dma_pageContext.get("method") ?? "")))), '' + dma_disclosureVo.get("reqObjDocAcpNo") + '');
            } else {
                parent.fn_registerProcess('' + dma_disclosureVo.get("applNo") + '', '' + dma_disclosureVo.get("docNo") + '', '' + dma_disclosureVo.get("formCd") + '', '' + dma_disclosureVo.get("formVer") + '', '' + dma_disclosureVo.get("wrtrptMaindocTpCd") + '', (String(((dma_pageContext.get("method") ?? "")) == null ? '' : ((dma_pageContext.get("method") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("method") ?? "")) == null ? '' : ((dma_pageContext.get("method") ?? "")))), (String(((dma_pageContext.get("exmptObjDisclsYn") ?? "")) == null ? '' : ((dma_pageContext.get("exmptObjDisclsYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("exmptObjDisclsYn") ?? "")) == null ? '' : ((dma_pageContext.get("exmptObjDisclsYn") ?? "")))));
            }
        } else {
            parent.registerMessage((String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? "")))));
        }
        if ((String(((dma_pageContext.get("registYn") ?? "")) == null ? '' : ((dma_pageContext.get("registYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("registYn") ?? "")) == null ? '' : ((dma_pageContext.get("registYn") ?? "")))) === 'Y' && '' + dma_disclosureVo.get("applNo") + ''.length === 14) {
            parent.fn_registerProcess('' + dma_disclosureVo.get("applNo") + '', '' + dma_disclosureVo.get("formCd") + '', '' + dma_disclosureVo.get("formVer") + '', '' + dma_disclosureVo.get("tgtIsurCd") + '', '' + dma_disclosureVo.get("tgtFssUnqNo") + '', '' + dma_disclosureVo.get("tgtComNm") + '', '' + dma_disclosureVo.get("tgtIsuSrtCd") + '', (String(((dma_pageContext.get("method") ?? "")) == null ? '' : ((dma_pageContext.get("method") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("method") ?? "")) == null ? '' : ((dma_pageContext.get("method") ?? "")))), (String(((dma_pageContext.get("exmptObjDisclsYn") ?? "")) == null ? '' : ((dma_pageContext.get("exmptObjDisclsYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("exmptObjDisclsYn") ?? "")) == null ? '' : ((dma_pageContext.get("exmptObjDisclsYn") ?? "")))));
        } else {
            parent.registerMessage((String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? "")))));
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00005.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
